import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'fs';
import { extname, join, relative } from 'path';
import { fileURLToPath } from 'url';
import { imageSize } from 'image-size';

// Must match the widths generated by the image-transmutation step in the CMS build workflow
// (public/cms/.github/workflows/update-website.yml)
const WIDTHS = ['500', '1000', '2000'];
const OPTIMIZED_FORMATS = ['png', 'webp'];
const IMAGE_EXTENSIONS = ['.jpg', '.jpeg', '.png', '.webp', '.avif'];

const MEDIA_DIR = 'public/cms/media';
const OPTIMIZED_MEDIA_DIR = 'public/cms/optimized-media';
const MANIFEST_PATH = 'src/data/generated/image-manifest.json';

/**
 * Builds a manifest of every CMS media image, with its real (source) dimensions and which
 * optimized/responsive variants (if any) currently exist on disk. This lets the `Image`
 * component set correct `width`/`height` attributes (needed for `sizes="auto"` to work), and
 * fall back to the unoptimized original whenever the optimized version hasn't been generated
 * yet - e.g. locally, right after adding a new image, before image-transmutation has run.
 */
export default function imageManifest() {
  let root;

  return {
    name: 'image-manifest',
    hooks: {
      'astro:config:setup': ({ config }) => {
        root = fileURLToPath(config.root);
        generateManifest(root);
      },
      // Keep the manifest fresh while `astro dev` is running, so newly added/optimized
      // images (e.g. from running image-transmutation locally) show up without restarting
      'astro:server:setup': ({ server }) => {
        const mediaDir = join(root, MEDIA_DIR);
        const optimizedDir = join(root, OPTIMIZED_MEDIA_DIR);

        server.watcher.add([mediaDir, optimizedDir]);

        let regenerateTimeout;
        const scheduleRegenerate = (path) => {
          if (!path.startsWith(mediaDir) && !path.startsWith(optimizedDir)) return;

          clearTimeout(regenerateTimeout);
          // Debounced, since image-transmutation writes many files in quick succession
          regenerateTimeout = setTimeout(() => {
            generateManifest(root);
            server.ws.send({ type: 'full-reload' });
          }, 300);
        };

        server.watcher.on('add', scheduleRegenerate);
        server.watcher.on('unlink', scheduleRegenerate);
        server.watcher.on('change', scheduleRegenerate);
      },
    },
  };
}

function generateManifest(root) {
  const mediaDir = join(root, MEDIA_DIR);
  const optimizedDir = join(root, OPTIMIZED_MEDIA_DIR);
  const outputPath = join(root, MANIFEST_PATH);

  const manifest = {};

  if (existsSync(mediaDir)) {
    for (const filePath of walk(mediaDir)) {
      const ext = extname(filePath).toLowerCase();
      if (!IMAGE_EXTENSIONS.includes(ext)) continue;

      const relativePath = relative(mediaDir, filePath).split('\\').join('/');
      const nameWithoutExt = relativePath.slice(0, -ext.length);
      const urlPath = `/cms/media/${relativePath}`;

      let dimensions;
      try {
        dimensions = imageSize(readFileSync(filePath));
      } catch {
        // Not a readable/supported image (e.g. corrupt file) - skip it, Image.svelte will
        // just render it without width/height/optimized variants
        continue;
      }

      // JPEG EXIF orientations 5-8 mean the image is rotated 90/270 degrees for display,
      // even though the raw pixel data (what imageSize reports) is stored un-rotated.
      // Swap width/height so the manifest reflects how the image actually renders
      // (image-transmutation's `sharp(...).rotate()` step already bakes this rotation in
      // when generating the optimized/resized variants).
      let { width, height } = dimensions;
      if (dimensions.orientation && dimensions.orientation >= 5) {
        [width, height] = [height, width];
      }

      const hasOptimized = OPTIMIZED_FORMATS.some((format) =>
        existsSync(join(optimizedDir, `${nameWithoutExt}.${format}`))
      );

      const availableWidths = WIDTHS.filter((imageWidth) =>
        OPTIMIZED_FORMATS.some((format) =>
          existsSync(join(optimizedDir, `${nameWithoutExt}-${imageWidth}w.${format}`))
        )
      );

      manifest[urlPath] = {
        width,
        height,
        hasOptimized,
        availableWidths,
      };
    }
  }

  mkdirSync(join(root, 'src/data/generated'), { recursive: true });
  writeFileSync(outputPath, JSON.stringify(manifest), 'utf-8');
}

function* walk(dir) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const fullPath = join(dir, entry.name);
    if (entry.isDirectory()) {
      yield* walk(fullPath);
    } else {
      yield fullPath;
    }
  }
}
